import{_ as t,o as a,c as i,a2 as d}from"./chunks/framework.CHeM0PsO.js";const b=JSON.parse('{"title":"Sovereign Mobile — Roadmap","description":"","frontmatter":{"sourceUrl":"https://github.com/sovereignfs/sovereign-mobile/blob/main/ROADMAP.md"},"headers":[],"relativePath":"apps/mobile/roadmap.md","filePath":"apps/mobile/roadmap.md"}'),o={name:"apps/mobile/roadmap.md"};function r(s,e,n,c,l,h){return a(),i("div",null,[...e[0]||(e[0]=[d('<h1 id="sovereign-mobile-—-roadmap" tabindex="-1">Sovereign Mobile — Roadmap <a class="header-anchor" href="#sovereign-mobile-—-roadmap" aria-label="Permalink to &quot;Sovereign Mobile — Roadmap&quot;">​</a></h1><p>Chronological task index and <strong>canonical task status</strong>. One row per task. Full detail for any task lives in <a href="./docs/epics/README.html">docs/epics/</a>; this file tracks only sequencing and status.</p><p>Epic task IDs (e.g. <code>20.1</code>) are permanent and shared with the <code>sovereign</code> monorepo&#39;s own <a href="https://github.com/sovereignfs/sovereign/blob/main/docs/epics/mobile.md" target="_blank" rel="noreferrer">epic 20</a> — cite them in commits, PRs, and cross-references. <strong>Roadmap slot versions</strong> below (<code>0.1.1</code>, <code>0.2.1</code>, …) are this repo&#39;s own and are volatile: they reflect current sequencing and shift when priorities change. Keep slots out of branch names and commit subjects.</p><p>This repo has not had a public release yet — see the Phase 1 definition of done below for that bar. Individual tasks land and ship to internal builds/testing ahead of that: Phase 2 (bridge transport) is done as of 2026-08. <a href="https://github.com/sovereignfs/sovereign/blob/main/docs/repositories.md" target="_blank" rel="noreferrer">docs/repositories.md</a> in the <code>sovereign</code> monorepo listed this repo&#39;s status as &quot;Not yet created&quot; as of 2026-07-31 — stale now that real code has landed; update it there when touching that doc next.</p><h2 id="phase-1-—-whole-instance-shell-sovereign-workstream-0002" tabindex="-1">Phase 1 — Whole-instance shell (sovereign workstream 0002) <a class="header-anchor" href="#phase-1-—-whole-instance-shell-sovereign-workstream-0002" aria-label="Permalink to &quot;Phase 1 — Whole-instance shell (sovereign workstream 0002)&quot;">​</a></h2><p>The reason this repository is created. Ships the universal app: onboarding, instance persistence/switching, WebView loading, store release. No device bridge beyond whatever thin slice RFC 0083 has landed centrally by the time this phase starts.</p><table tabindex="0"><thead><tr><th>Slot</th><th>Task</th><th>Status</th><th>Epic task</th></tr></thead><tbody><tr><td>0.1.1</td><td>Capacitor shell scaffold</td><td>⏳</td><td><a href="./docs/epics/shell.html#-201--capacitor-shell-scaffold">20.1</a></td></tr><tr><td>0.1.2</td><td>Store release setup and privacy declarations (iOS + Android)</td><td>📋</td><td><a href="./docs/epics/release.html#-204--store-release-setup-and-privacy-declarations">20.4</a></td></tr><tr><td>0.1.3</td><td><code>sovereign://</code> deep link scheme</td><td>✅</td><td><a href="./docs/epics/shell.html#-2014--sovereign-deep-link-scheme">20.14</a></td></tr></tbody></table><p><strong>Prerequisites, owned in the <code>sovereign</code> monorepo, gate this phase but are not this repo&#39;s own work:</strong> the WKWebView offline spike (task 20.10), the instance identity/validation endpoint (task 20.2), and the in-app text-size control that discharges the pinch-zoom accessibility debt (task 10.2). See sovereign workstream 0002 for that sequencing; this repo&#39;s leg 4/5 can begin once workstream 0002&#39;s leg 1 gate clears and leg 2&#39;s response contract is agreed (not necessarily merged).</p><h2 id="phase-2-—-bridge-transport" tabindex="-1">Phase 2 — Bridge transport <a class="header-anchor" href="#phase-2-—-bridge-transport" aria-label="Permalink to &quot;Phase 2 — Bridge transport&quot;">​</a></h2><p>This shell&#39;s implementation of the shared device capability bridge (sovereign RFC 0083). Nothing in this phase starts before the protocol itself (<code>@sovereignfs/bridge</code>, <code>@sovereignfs/sdk/device-client</code>) exists centrally.</p><table tabindex="0"><thead><tr><th>Slot</th><th>Task</th><th>Status</th><th>Epic task</th></tr></thead><tbody><tr><td>0.2.1</td><td>Mobile SDK native environment and bridge adapter (Capacitor transport of <code>@sovereignfs/bridge</code>)</td><td>✅</td><td><a href="./docs/epics/bridge.html#-203--mobile-sdk-native-environment-and-bridge-adapter">20.3</a></td></tr></tbody></table><h2 id="phase-3-—-capability-breadth" tabindex="-1">Phase 3 — Capability breadth <a class="header-anchor" href="#phase-3-—-capability-breadth" aria-label="Permalink to &quot;Phase 3 — Capability breadth&quot;">​</a></h2><p>Each row is an additive registry entry against the same bridge contract, not a new mechanism. Sequencing here is not strict — these can land in any order once Phase 2 ships, as product need identifies them.</p><table tabindex="0"><thead><tr><th>Slot</th><th>Task</th><th>Status</th><th>Epic task</th></tr></thead><tbody><tr><td>0.3.1</td><td>Native push notifications (APNs/FCM)</td><td>✅</td><td><a href="./docs/epics/bridge.html#-205--native-push-notifications-apnsfcm">20.5</a></td></tr><tr><td>0.3.2</td><td>Native photo picker and camera capture</td><td>✅</td><td><a href="./docs/epics/bridge.html#-206--native-photo-picker-and-camera-capture">20.6</a></td></tr><tr><td>0.3.3</td><td>Biometric auth capability</td><td>✅</td><td><a href="./docs/epics/bridge.html#-207--biometric-auth-capability">20.7</a></td></tr><tr><td>0.3.4</td><td>Haptics capability</td><td>✅</td><td><a href="./docs/epics/bridge.html#-208--haptics-capability">20.8</a></td></tr><tr><td>0.3.5</td><td>Background capability planning</td><td>📋</td><td><a href="./docs/epics/bridge.html#-209--background-capability-planning">20.9</a></td></tr><tr><td>0.3.6</td><td>Encrypted secure-storage capability (SQLCipher database; iOS verified, Android build-only)</td><td>🚧</td><td><a href="./docs/epics/bridge.html#-2013--encrypted-secure-storage-capability-sovereign-rfc-0093-leg-4">20.13</a></td></tr></tbody></table><p>Further candidates (geolocation, calendar, NFC, and others) are tracked as open questions, not roadmap rows, in <a href="./docs/research/0002-device-capability-candidates.html">docs/research/0002-device-capability-candidates.md</a> until a concrete plugin need graduates one onto this list.</p><h2 id="phase-4-—-focused-plugin-apps" tabindex="-1">Phase 4 — Focused plugin apps <a class="header-anchor" href="#phase-4-—-focused-plugin-apps" aria-label="Permalink to &quot;Phase 4 — Focused plugin apps&quot;">​</a></h2><p>Separately gated (sovereign workstream 0001, RFC 0082). Publishing individual, single-plugin apps from this same codebase.</p><table tabindex="0"><thead><tr><th>Slot</th><th>Task</th><th>Status</th><th>Epic task</th></tr></thead><tbody><tr><td>0.4.1</td><td>Focused plugin app build targets</td><td>📋</td><td><a href="./docs/epics/release.html#-2011--focused-plugin-app-build-targets">20.11</a></td></tr><tr><td>0.4.2</td><td>Plugin app store release process and rationing policy</td><td>📋</td><td><a href="./docs/epics/release.html#-2012--plugin-app-store-release-process-and-rationing-policy">20.12</a></td></tr></tbody></table><h2 id="definition-of-done-—-phase-1-public-release" tabindex="-1">Definition of done — Phase 1 public release <a class="header-anchor" href="#definition-of-done-—-phase-1-public-release" aria-label="Permalink to &quot;Definition of done — Phase 1 public release&quot;">​</a></h2><p>Restated from sovereign workstream 0002, since it&#39;s the concrete bar for this repo&#39;s first shipped version:</p><ul><li>[ ] Published on the App Store and Play Store (public release, not just an internal track).</li><li>[ ] First launch prompts for an instance URL, validates it, and loads the instance; a stored instance loads directly on relaunch.</li><li>[ ] An invalid or unreachable URL fails with an inline error and does not crash.</li><li>[ ] A non-Sovereign URL is rejected as such, not merely as &quot;unreachable&quot;.</li><li>[ ] Users can add, remove, and switch between at least two instances.</li><li>[ ] External links open outside the primary WebView.</li><li>[ ] Offline behavior matches the scope decided by the offline spike&#39;s finding, and whatever is not supported is documented rather than silently broken.</li><li>[ ] No Sovereign auth, role, or plugin behavior is duplicated in native code.</li><li>[ ] <code>docs/repositories.md</code> in the <code>sovereign</code> monorepo reflects this repo&#39;s actual status once created and shipping.</li></ul><h2 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Version</th><th>Date</th><th>Change</th></tr></thead><tbody><tr><td>0.1</td><td>2026-07-31</td><td>Initial roadmap</td></tr><tr><td>0.2</td><td>2026-08-03</td><td>Phase 2 (20.3, bridge adapter) done; 20.8 (haptics) closed as subsumed by 20.3</td></tr><tr><td>—</td><td>2026-08-08</td><td>20.6 (native photo picker / camera capture) done — landed without its own version bump at the time</td></tr><tr><td>0.3</td><td>2026-08-09</td><td>20.7 (biometric auth capability) done — iOS and Android build/launch-verified (JDK 21 installed this session)</td></tr><tr><td>0.4</td><td>2026-08-09</td><td>20.14 (<code>sovereign://</code> deep link scheme) done — two real cross-platform bugs found and fixed along the way (iOS WKUserScript aliasing, Android Chromium URL-authority parsing); see docs/epics/shell.md and ADR 0008</td></tr><tr><td>0.5</td><td>2026-08-09</td><td>20.5 (native push notifications, RFC 0087 leg 4) done — native iOS/Android push clients, on-device P-256 keypair generation, payload decryption; no new bridge capability, per RFC 0083 §7</td></tr><tr><td>0.6</td><td>2026-08-13</td><td>20.13 (encrypted secure-storage capability, sovereign RFC 0093 leg 4) partial — Keychain/Keystore key custody done and build-verified both platforms, <code>@capacitor-community/sqlite</code>/SQLCipher database not started (tracked under sovereign epic task 8.20); no interactive prompt verified yet, no real caller exists (matches 20.7&#39;s own shipped state). Also fixed a pre-existing bug found along the way: <code>biometrics.confirm</code> (20.7) was dispatched but never advertised in either platform&#39;s handshake <code>capabilities</code> array.</td></tr><tr><td>0.7</td><td>2026-08-14</td><td>20.13 (secure-storage capability, completion) still 🚧 partial — <code>@capacitor-community/sqlite</code> turned out unusable as designed (its API is JS-facing and this shell strips Capacitor&#39;s own bridge from remote content), replaced with direct SQLCipher linking (<code>SQLCipher.swift</code> SPM on iOS, <code>net.zetetic:sqlcipher-android</code> + <code>androidx.sqlite:sqlite</code> on Android). <code>SecureDatabase.swift</code>/<code>SecureDatabase.java</code> built, build-verified both platforms, and interactively verified end-to-end on iOS (a real device-credential round-trip, plus the <code>sovereign</code> monorepo&#39;s <code>example-device-only</code> reference plugin surviving a full app kill/relaunch). Android reaches a real credential-confirmation dialog once a device credential is configured, but this AVD image&#39;s SystemUI reproducibly wedges on PIN/credential screens, blocking confirmation of the completed <code>ok</code> path — an emulator-specific issue, not a code defect. Also fixed, on the <code>sovereign</code> monorepo side: <code>DeviceStorageKeySection.tsx</code> and <code>device-only-kv.ts</code> were both unreachable/inert on native shells, independent of this repo&#39;s own code — see that repo&#39;s own PR for detail.</td></tr></tbody></table>',23)])])}const g=t(o,[["render",r]]);export{b as __pageData,g as default};
